SELECT o.outcome, COUNT(*) AS count, CAST(COUNT(*) AS FLOAT) / NULLIF((SELECT COUNT(*) FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 77 AND 87 AND a.admission_type_id = 1), 0) AS proportion FROM (SELECT CASE WHEN hs_tn_t = 'N' THEN 'Normal' WHEN hs_tn_t = 'B' THEN 'Borderline' WHEN hs_tn_t = 'M' THEN 'Myocardial Injury' END AS outcome FROM labevents) GROUP BY outcome;